SELECT   
AND r.api_id > #{afterApiId}
ORDER BY r.api_id LIMIT #{limit}

SELECT api_id,code,name,enabled,total FROM (
    SELECT m.api_id,t.code,t.name,t.enabled,COUNT(*) OVER(PARTITION BY m.api_id) AS total,
           ROW_NUMBER() OVER(PARTITION BY m.api_id ORDER BY t.name,t.id) AS membership_rank
    FROM mcp_tool_set_member m JOIN mcp_tool_set t ON t.id=m.tool_set_id
    WHERE t.environment_id=#{environmentId} AND m.environment_id=#{environmentId} AND m.api_id IN #{id}
) memberships WHERE membership_rank <= 3 ORDER BY api_id,name,code
